import { InputValidator, isDefined } from '@aenode/material/validators';
import { Directive, inject, input, model, OnInit, signal } from '@angular/core';
import { ControlValueAccessor, FormControl, NgControl } from '@angular/forms';

export type InputOption<T> = {
  id?: string;
  label: string;
  value: T;
};

@Directive()
export abstract class BaseInput<ValueType = any>
  implements ControlValueAccessor, OnInit
{
  /**
   * Custom validators built on top of Validators class.
   */
  inputValidator = inject(InputValidator);

  // Validators

  /**
   * Mark field as requried
   */
  required = input<boolean>(false);
  /**
   * Enforce minimum length
   */
  minlength = input<number>(1);

  /**
   * Enforce maximum length
   */
  maxlength = input<number>(400);

  /**
   * Enforce minimum items for list inputs
   */
  minitems = input<number>(0);
  /**
   * Enforce maximum items for list inputs
   */
  maxitems = input<number>(Number.MAX_SAFE_INTEGER);

  /**
   * Enforce minimum number value
   */
  min = input<number>(Number.MIN_SAFE_INTEGER);
  /**
   * Enforce maximum number value
   */
  max = input<number>(Number.MAX_SAFE_INTEGER);

  /**
   * Enforce email pattern matching
   */
  email = input<boolean>(false);

  /**
   * Enforce password pattern matching
   */
  password = input<boolean>(false);

  /**
   * Options for selectable inputs such as select, autocomplete, button-toggle, radio and so on
   */
  options = input<InputOption<ValueType>[]>([]);

  /**
   * Allow multiple selection for selectable components
   */
  multiple = input<boolean>(false);

  //
  /**
   * Input label
   */
  label = input<string>('');

  /**
   * Input placeholder
   */
  placeholder = input<string>('');

  /**
   * Input value hints/explanations/format/pattern etc.
   */
  hint = input<string>('');

  /**
   * Default input value
   */
  defaultValue = input<ValueType | null>(null);

  value = model<ValueType>();
  /**
   * Define the input field disabled or enabled
   */
  disabled = signal<boolean>(false);

  /**
   * Reactive FormControl instance
   */
  formControl = signal<FormControl>(new FormControl());

  /**
   * Prefix icon
   */
  iconPrefix = input<string>();

  /**
   * Suffix icon
   */
  iconSuffix = input<string>();

  /**
   * Prefix text
   */
  textPrefix = input<string>();

  /**
   * Suffix text
   */
  textSuffix = input<string>();

  constructor() {
    this.__setValueAccessor();
    this.__setDefaultValue();
  }
  protected onChange: (value: ValueType | null) => void = () => {
    //
  };
  protected onTouched: () => void = () => {
    //
  };

  writeValue(_value: ValueType): void {
    //
  }
  readonly ngControl = inject(NgControl, { self: true, optional: true });

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  /**
   * Resolve error message from formControl errors
   * @returns error message
   */
  protected errorMessage() {
    const errors = this.formControl().errors;
    if (errors) {
      const [constraint, constraintValue] = Object.entries(errors)[0];
      return this.inputValidator.errorMessage(
        this.formControl().value,
        constraint,
        constraintValue,
      );
    }

    return null;
  }

  /**
   * Reset the form control
   */
  reset() {
    this.formControl().reset();
    this.formControl().setErrors(null);
  }

  ngOnInit(): void {
    this.__setValueAccessor();
    this.__setDefaultValue();
  }

  private __setValueAccessor() {
    if (this.ngControl) {
      this.ngControl.valueAccessor = this;
    }
  }

  private __setDefaultValue() {
    const __control = this.ngControl?.control as FormControl;

    if (isDefined(__control)) {
      this.formControl.update(() => __control as FormControl);

      const __defaultValue = this.defaultValue();
      if (isDefined(__defaultValue)) {
        this.setDefaultValue(__control, __defaultValue);
      }
    }
  }

  protected transformValue(value: ValueType): any {
    return value;
  }

  /**
   * Set value to the form control without firing event
   * @param control
   * @param value
   */
  protected setDefaultValue(control: FormControl, value: ValueType) {
    const tValue = this.transformValue(value);
    control.setValue(tValue, { emitEvent: false });
    this.value.update(() => tValue);
  }
}

import { Color, colorVar } from '@aenode/material/common';
import { computed, Directive, input } from '@angular/core';

/**
 * Directive to set elements's style color from the angular-theme variables
 */
@Directive({
  selector: `[aeColor]`,
  host: {
    '[style.color]': 'aeColorComputed()',
  },
})
export class ColorDirective {
  /**
   * Text color variable {@link Color}
   */
  aeColor = input.required<Color>();

  protected aeColorComputed = computed(() => colorVar(this.aeColor()));
}

/**
 * Directive to set elements's style color from the angular-theme variables
 */
@Directive({
  selector: `[aeBgColor]`,
  host: {
    '[style.backgroundColor]': 'aeBgColorComputed()',
  },
})
export class BgColorDirective {
  /**
   * Background color variable {@link Color}
   */
  aeBgColor = input.required<Color>();

  protected aeBgColorComputed = computed(() => colorVar(this.aeBgColor()));
}

import { FlexModule } from '@aenode/material/flex';
import { Component, Directive, input } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatIconModule } from '@angular/material/icon';

@Directive({
  selector: 'button[aeCardAction],[aeCardAction]',
})
export class CardActionDirective {}

@Component({
  selector: 'ae-card',
  imports: [FlexModule, MatCardModule, MatButtonModule, MatIconModule],
  template: `
    <mat-card>
      <mat-card-header>
        @if (avatarSrc()) {
          <img matCardAvatar [src]="avatarSrc()" [alt]="avatarAlt()" />
        }
        @if (title()) {
          <mat-card-title>{{ title() }}</mat-card-title>
        }
        @if (subTitle()) {
          <mat-card-subtitle>{{ subTitle() }}</mat-card-subtitle>
        }
      </mat-card-header>

      @if (imgSrc()) {
        <img matCardImage [src]="imgSrc()" [alt]="imgAlt()" />
      }

      @if (content()) {
        <mat-card-content>
          @for (c of content(); track c) {
            <p>{{ c }}</p>
          }
        </mat-card-content>
      }
      <mat-card-actions>
        <div vnFlexRow vnFlexFull vnFlexWrap vnFlexCenter vnFlexGap>
          <ng-content select="button[vnCardAction]"></ng-content>
        </div>
      </mat-card-actions>
    </mat-card>
  `,
})
export class CardComponent {
  title = input<string>();
  subTitle = input<string>();
  content = input<string[]>([]);

  avatarSrc = input<string>();
  avatarAlt = input<string>();

  imgSrc = input<string>();
  imgAlt = input<string>();
}

