import { Component, input } from '@angular/core';

export type InputType =
  | 'text'
  | 'number'
  | 'integer'
  | 'date'
  | 'time'
  | 'autocomplete'
  | 'list'
  | 'select'
  | 'slide'
  | 'button-toggle'
