  children?: MenuItem[];
  icon?: string;
  matMenu?: MatMenu;
};

@Component({
  selector: 'ae-menu',
  imports: [
    RouterModule,
    MatMenuModule,
    MatButtonModule,
    MatIconModule,
    MatFormFieldModule,
  ],
  template: `
    @if (isSubMenuItems()) {
      <mat-menu #menu>
        @for (item of items(); track item) {
          @if (item.children) {
            <button mat-menu-item [matMenuTriggerFor]="item.matMenu!">
              {{ item.label }}
            </button>
          } @else {
            <button mat-menu-item [routerLink]="item.route">
              {{ item.label }}
            </button>
          }
        }
      </mat-menu>
    } @else {
      <!-- Main Menu Items -->
      @for (item of items(); track item) {
        @if (item.children) {
          <button matButton [matMenuTriggerFor]="item.matMenu!">
            {{ item.label }}
          </button>
        } @else {
          <button matButton [routerLink]="item.route">{{ item.label }}</button>
        }
      }
    }

    <!-- Create menues -->
    @for (item of items(); track item) {
      @if (item.children) {
        <ae-menu
          #newMenu
          [items]="item.children"
          [isSubMenuItems]="true"
        ></ae-menu>
        {{ assignMenu(item, newMenu.childMenu) }}
      }
    }
  `,
})
export class MenuComponent {
  items = input.required<MenuItem[]>();
  protected isSubMenuItems = input<boolean>(false);
  @ViewChild('menu') childMenu!: MatMenu;

  protected assignMenu(item: MenuItem, menu: MatMenu) {
    item.matMenu = menu;
  }
}

