import {
  Component,
  computed,
  contentChildren,
  model,
  NgModule,
  signal,
} from '@angular/core';
import { InputModelDirective } from './input-model';

@Component({
  selector: 'ae-form, [aeForm]',
  exportAs: 'aeForm',
  template: `
    <form aeFlexCol aeFlexGap>
      <ng-content></ng-content>
    </form>
  `,
})
export class FormModelComponent {
  readonly errors = model<any>();

  readonly inputs = contentChildren(InputModelDirective);
  readonly value = model<any>();
  readonly isSubmitted = signal<boolean>(false);

  readonly isValid = computed(() => {
    return this.inputs().every((e) => e.isValid() && e.isTouched());
  });

  readonly isInvalid = computed(() => {
    return this.inputs().some((e) => e.isInvalid() && e.isTouched());
  });

  readonly isTouched = computed(() => {
    return this.inputs().some((e) => e.isTouched());
  });

  readonly isDirty = computed(() => {
    return this.inputs().some((e) => e.isDirty());
  });

  getInput(name: string) {
    return this.inputs().find((e) => e.name() === name);
  }

  markAsDirty(name: string) {
    this.getInput(name)?.isDirty.set(true);
  }

  markAsTouched(name: string) {
    this.getInput(name)?.isTouched.set(true);
  }

  markAsValid(name: string) {
    this.getInput(name)?.isValid.set(true);
  }

  markAsInvalid(name: string) {
    this.getInput(name)?.isInvalid.set(true);
  }

  set(value: Record<string, any>) {
    const entries = Object.entries(value);
    for (const [key, value] of entries) {
      this.getInput(key)?.set(value);
    }
  }

  reset() {
    this.inputs().forEach((e) => e.reset());
  }
}

@NgModule({
  imports: [FormModelComponent, InputModelDirective],
  exports: [FormModelComponent, InputModelDirective],
})
export class FormModelModule {}

import { FlexModule } from '@aenode/material/flex';
import { BaseInput } from '@aenode/material/input';
import { CdkTrapFocus } from '@angular/cdk/a11y';
import {
  Component,
  contentChildren,
  Directive,
  input,
  NgModule,
  output,
} from '@angular/core';
import { FormGroup } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';

/**
 * Positional directive to define the form action buttons location
 */
@Directive({ selector: '[aeFormAction]' })
export class FormActionDirective {}

/**
 * Form container component that renders input components and form actions
 */
@Component({
  selector: 'ae-form, [vnForm]',
  imports: [FlexModule, MatButtonModule, MatIconModule, CdkTrapFocus],
  exportAs: 'vnForm',
  template: `
    <div vnFlexCol vnFlexGap cdkTrapFocus>
      <ng-content
        select="ae-input, [vnInput], ae-input-field, [vnInputField]"
      ></ng-content>
      <div vnFlexRow vnFlexGap>
        <!-- Submit button -->
        <button
          [disabled]="this.formGroup().invalid"
          type="button"
          mat-raised-button
          (click)="submit()"
        >
          {{ submitLabel() }}
        </button>

        <!-- Reset button -->
        @if (!hideResetButton()) {
          <button mat-flat-button (click)="reset()">{{ resetLabel() }}</button>
        }

        <!-- Other action buttons -->
        <ng-content select="button[vnFormAction]"></ng-content>
      </div>
    </div>
  `,
})
export class FormComponent {
  /**
   * List of input components
   */
  readonly formInputs = contentChildren<BaseInput>(BaseInput, {
    descendants: true,
  });
  /**
   * Submit button label
   */
  readonly submitLabel = input<string>('Submit');

  /**
   * Reset button label
   */
  readonly resetLabel = input<string>('Reset');

  /**
   * Reactive form group instance
   */
  readonly formGroup = input.required<FormGroup>();

  /**
   * Hide reset button
   */
  readonly hideResetButton = input<boolean>(false);

  /**
   * Event to fire when the submit button is clicked.
   */
  readonly formSubmitEvet = output();

  /**
   * Smit the form value
   */
  submit() {
    this.formSubmitEvet.emit(this.formGroup().value);
  }

  /**
   * Reset the form value
   */
  reset() {
    this.formGroup().reset();
  }
}

/**
 * Form module that provides {@link FormComponent} and {@link FormActionDirective}
 */
@NgModule({
  imports: [FormComponent, FormActionDirective],
  exports: [FormComponent, FormActionDirective],
})
export class FormModule {}

